From 9a488ac39ecc6d625b2ddde4af18fa3df0fce060 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 11:36:17 +0100
Subject: [PATCH] notifier: keep the tray item registered when there is nothing
 to show

The status notifier item was deleted whenever there were no updates, so
the System Tray settings had no Updates entry to configure and "Always
show" did nothing. Keep the item around and switch it to Passive instead.

BUG: 495651
---
 notifier/NotifierItem.cpp | 37 ++++++++++++-------------------------
 notifier/NotifierItem.h   |  1 -
 2 files changed, 12 insertions(+), 26 deletions(-)

diff --git a/notifier/NotifierItem.cpp b/notifier/NotifierItem.cpp
index dff22e3d4..8a9ca1242 100644
--- a/notifier/NotifierItem.cpp
+++ b/notifier/NotifierItem.cpp
@@ -50,7 +50,11 @@ void NotifierItem::setupNotifierItem()
     auto refreshAction = menu->addAction(QIcon::fromTheme(QStringLiteral("view-refresh")), i18n("Refresh…"));
     connect(refreshAction, &QAction::triggered, &m_notifier, &DiscoverNotifier::recheckSystemUpdateNeededAndNotifyApp);

-    if (m_notifier.needsReboot()) {
+    auto f = [this, menu]() {
+        m_item->setTitle(i18n("Restart to apply installed updates"));
+        m_item->setToolTipTitle(i18n("Click to restart the system"));
+        m_item->setIconByName(QStringLiteral("system-reboot-update"));
+
         menu->addSeparator();

         auto rebootAction = menu->addAction(QIcon::fromTheme(QStringLiteral("system-reboot-update")), i18n("Install Updates and Restart…"));
@@ -58,12 +62,6 @@ void NotifierItem::setupNotifierItem()

         auto shutdownAction = menu->addAction(QIcon::fromTheme(QStringLiteral("system-shutdown-update")), i18n("Install Updates and Shut Down…"));
         connect(shutdownAction, &QAction::triggered, &m_notifier, &DiscoverNotifier::shutdownPrompt);
-    }
-
-    auto f = [this]() {
-        m_item->setTitle(i18n("Restart to apply installed updates"));
-        m_item->setToolTipTitle(i18n("Click to restart the system"));
-        m_item->setIconByName(QStringLiteral("system-reboot-update"));
     };
     if (m_notifier.needsReboot())
         f();
@@ -76,18 +74,18 @@ void NotifierItem::setupNotifierItem()
         menu->addAction(action);
     });
     m_item->setContextMenu(menu);
-    m_item->setStatus(KStatusNotifierItem::Active);
-    refresh();
 }

 void NotifierItem::refreshStatusNotifierVisibility()
 {
-    bool shouldShow = shouldShowStatusNotifier();
-    if (!m_item && shouldShow) {
-        setStatusNotifierVisibility(true);
-    } else if (m_item && !shouldShow) {
-        setStatusNotifierVisibility(false);
+    if (!isStatusNotifierEnabled()) {
+        delete m_item;
+        return;
+    }
+    if (!m_item) {
+        setupNotifierItem();
     }
+    m_item->setStatus(shouldShowStatusNotifier() ? KStatusNotifierItem::Active : KStatusNotifierItem::Passive);
     refresh();
 }

@@ -106,17 +104,6 @@ void NotifierItem::refresh()
     m_item->setToolTipSubTitle(m_notifier.message());
 }

-void NotifierItem::setStatusNotifierVisibility(bool visible)
-{
-    if (visible) {
-        Q_ASSERT(!m_item);
-        setupNotifierItem();
-    } else {
-        Q_ASSERT(m_item);
-        delete m_item;
-    }
-}
-
 bool NotifierItem::shouldShowStatusNotifier() const
 {
     if (!isStatusNotifierEnabled()) {
diff --git a/notifier/NotifierItem.h b/notifier/NotifierItem.h
index 01a4524d5..466e21fce 100644
--- a/notifier/NotifierItem.h
+++ b/notifier/NotifierItem.h
@@ -29,7 +29,6 @@ private:
     // Whether the Status Notifier Item is enabled; if disabled it will never be shown
     bool m_statusNotifierEnabled = false;
     void refreshStatusNotifierVisibility();
-    void setStatusNotifierVisibility(bool visible);
     bool shouldShowStatusNotifier() const;
     DiscoverNotifier m_notifier;
     QPointer<KStatusNotifierItem> m_item;
